"""Task execution helpers."""
import os, subprocess, sys
from templating import render, resolve_vars


def _subst(s, values):
    return render(s, values)


def run_tasks(config, names, *, cwd=None, dry=False, silent=False, force=False, cli_args='', cli_vars=None, exit_code=False):
    """Run task definitions from normalized Taskfile dictionary. Return exit status."""
    tasks=config.get('tasks') or {}
    cwd=cwd or os.getcwd()
    values=resolve_vars(config.get('vars') or {}, env=os.environ)
    values.update(cli_vars or {})
    values['CLI_ARGS']=cli_args
    active=set(); done=set()
    if not names: names=['default']
    def run(name):
        if name in done: return 0
        if name in active:
            print('task: Task called too many times (recursion limit)',file=sys.stderr); return 204
        task=tasks.get(name)
        if task is None:
            print(f'task: Task "{name}" does not exist',file=sys.stderr); return 200
        if isinstance(task,str): task={'cmds':[task]}
        elif isinstance(task,list): task={'cmds':task}
        task=task or {}; active.add(name)
        local_values=dict(values)
        task_env=dict(config.get('env') or {})
        task_env.update(task.get('env') or {})
        child_env=os.environ.copy()
        for key, value in task_env.items():
            if isinstance(value,dict) and 'sh' in value:
                try: value=subprocess.check_output(value['sh'],shell=True,cwd=cwd,env=child_env,text=True).rstrip('\n')
                except Exception: value=''
            resolved=_subst(value, local_values)
            child_env[str(key)]=str(resolved)
            local_values[str(key)]=resolved
        for key, value in (task.get('vars') or {}).items():
            local_values[key]=_subst(value, local_values)
        deps=task.get('deps', []) or []
        if isinstance(deps,str): deps=[deps]
        for dep in reversed(deps):
            if isinstance(dep,dict): dep=dep.get('task','')
            if dep and (rc:=run(str(dep))): active.remove(name); return rc
        for item in task.get('cmds',[]) or []:
            if isinstance(item,str): cmd=item; task_silent=False
            elif isinstance(item,dict):
                cmd=item.get('cmd',''); task_silent=item.get('silent',False)
            else: continue
            ignore_error=bool(item.get('ignore_error',False)) if isinstance(item,dict) else False
            cmd=_subst(cmd,local_values)
            if not cmd: continue
            if not silent and not task.get('silent',False) and not task_silent:
                print(f'task: [{name}] {cmd}',flush=True)
            if not dry:
                task_dir=_subst(task.get('dir',cwd),local_values)
                proc=subprocess.run(cmd,shell=True,cwd=task_dir,env=child_env)
                if proc.returncode and not ignore_error:
                    print(f'task: Failed to run task \"{name}\": exit status {proc.returncode}',file=sys.stderr)
                    active.remove(name); return proc.returncode if exit_code else 201
        active.remove(name); done.add(name); return 0
    for name in names:
        rc=run(name)
        if rc:return rc
    return 0
"""Task information modes (summary and status checks)."""
import os
import subprocess
import sys
import re


def _template(value, vars):
    def replace(match):
        key = match.group(1)
        return str(vars.get(key, os.environ.get(key, "")))
    return re.sub(r"{{\s*\.([A-Za-z_][\w]*)\s*}}", replace, str(value))


def _commands(task):
    if isinstance(task, str):
        return [task]
    if isinstance(task, list):
        return task
    task = task or {}
    cmds = task.get("cmds", []) or []
    if not cmds and task.get("cmd"):
        cmds = [task["cmd"]]
    return cmds


def show_summary(config, name, taskfile="", cwd=None):
    """Print the reference-style summary for one normalized task."""
    tasks = config.get("tasks") or {}
    task = tasks.get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    obj = task if isinstance(task, dict) else {}
    vars = dict(config.get("vars") or {})
    print(f"task: {name}")
    print()
    desc = obj.get("summary") or obj.get("desc", "")
    if desc:
        print(_template(desc, vars))
    print()
    if vars:
        print("vars:")
        for key, value in vars.items():
            # Task's summary uses YAML-compatible quoted strings for scalars.
            if isinstance(value, str):
                val = '"' + value.replace('\\', '\\\\').replace('"', '\\"') + '"'
            elif value is None:
                val = "null"
            elif isinstance(value, bool):
                val = str(value).lower()
            else:
                val = str(value)
            print(f"  {key}: {val}")
        print()
    cmds = _commands(task)
    rendered = []
    for command in cmds:
        if isinstance(command, dict):
            command = command.get("cmd", "")
        if command:
            rendered.append(_template(command, vars))
    if rendered:
        print("commands:")
        for command in rendered:
            print(f" - {command}")
    return 0


def check_status(config, name, cwd=None):
    """Return success only when status commands all report the task current."""
    task = (config.get("tasks") or {}).get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    task = task if isinstance(task, dict) else {}
    checks = task.get("status") or []
    if isinstance(checks, str):
        checks = [checks]
    env = os.environ.copy()
    for key, value in (config.get("vars") or {}).items():
        env[str(key)] = str(value)
    for check in checks:
        try:
            if subprocess.run(str(check), shell=True, cwd=cwd, env=env,
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
                break
        except OSError:
            break
    else:
        if checks:
            return 0
    print(f'task: Task "{name}" is not up-to-date', file=sys.stderr)
    return 1
