        argv=argv[:split_at]
    else:
        cli_args_list=[]
    short_aliases={'-ls':['--list','--silent'],'-as':['--list-all','--silent'],'-la':['--list','--list-all'],'-al':['--list','--list-all'],'-aj':['--list-all','--json']}
    argv=[part for a in argv for part in short_aliases.get(a,[a])]

    known_long={'--color','--completion','--concurrency','--dir','--disable-fuzzy','--dry','--exit-code','--experiments','--failfast','--force','--global','--help','--init','--insecure','--interactive','--interval','--json','--list','--list-all','--nested','--no-status','--output','--output-group-begin','--output-group-end','--output-group-error-only','--parallel','--silent','--sort','--status','--summary','--taskfile','--verbose','--version','--watch','--yes'}
    known_short=set('cCdnxFfghiljopstv wyaI'.replace(' ',''))
    for arg in argv:
        if arg=='--': break
        if arg.startswith('--'):
            opt=arg.split('=',1)[0]
            if opt not in known_long:
                show_help()
                print(f'unknown flag: {opt}',file=sys.stderr); return 2
        elif re.match(r'^-[A-Za-z]=',arg):
            if arg[1] not in known_short:
                show_help()
                print(f"unknown shorthand flag: '{arg[1]}' in {arg}",file=sys.stderr); return 2
        elif arg.startswith('-') and arg != '-' and len(arg)==2 and arg[1] not in known_short:
            show_help()
            print(f"unknown shorthand flag: '{arg[1]}' in {arg}",file=sys.stderr); return 2
        elif arg.startswith('-') and not arg.startswith('--') and len(arg)>2 and arg[1] not in 'CdtoI':
            unknown=next((ch for ch in arg[1:] if ch not in known_short),None)
            if unknown:
                show_help()
                print(f"unknown shorthand flag: '{unknown}' in {arg}",file=sys.stderr); return 2
    if ('--list' in argv or '-l' in argv) and ('--list-all' in argv or '-a' in argv):
        print('task: cannot use --list and --list-all at the same time',file=sys.stderr)
        return 1
    if '--version' in argv: print('3.51.1'); return 0
    if '-h' in argv or '--help' in argv:
        show_help()
        return 0
    if '--experiments' in argv:
        print('* GENTLE_FORCE:     off\n* REMOTE_TASKFILES: off\n* ENV_PRECEDENCE:   off'); return 0
    if '--completion' in argv or any(a.startswith('--completion=') for a in argv):
        try: shell=next(a.split('=',1)[1] for a in argv if a.startswith('--completion='))
        except StopIteration:
            try: shell=argv[argv.index('--completion')+1]
            except: shell=''
        return run_completion(shell)
    user_working_dir=os.path.abspath(os.getcwd())
    cwd=os.getcwd(); taskfile=''; dry='--dry' in argv or '-n' in argv; silent='--silent' in argv or '-s' in argv
    init='--init' in argv or '-i' in argv
    dir_value=next((a.split('=',1)[1] for a in argv if a.startswith('--dir=')),None)
    if dir_value is not None: cwd=os.path.abspath(dir_value)
    elif '--dir' in argv or '-d' in argv:
        key='--dir' if '--dir' in argv else '-d'
        try: cwd=os.path.abspath(argv[argv.index(key)+1])
        except: pass
    taskfile_value=next((a.split('=',1)[1] for a in argv if a.startswith('--taskfile=')),None)
    if taskfile_value is not None: taskfile=taskfile_value
    elif '--taskfile' in argv or '-t' in argv:
        key='--taskfile' if '--taskfile' in argv else '-t'
        try: taskfile=argv[argv.index(key)+1]
        except: pass
    if init:
        target=None
        found=False
        takes_value={'--dir','-d','--taskfile','-t','--concurrency','-C','--output','-o','--sort','--interval','-I'}
        skip_value=False
        for arg in argv:
            if not found:
                if arg in ('--init','-i'):
                    found=True
                continue
            if skip_value:
                skip_value=False
                continue
            if arg in takes_value:
                skip_value=True
                continue
            if arg.startswith('--') or arg in ('-s','-v','-n','-f','-p'):
                continue
            if arg.startswith('-') and '=' in arg:
                continue
            target=arg
            break
        return run_init(cwd,target)
    path, root = find_taskfile(cwd, taskfile or None, '-g' in argv or '--global' in argv)
    if path == '-':
        cfg=parse_yaml(sys.stdin.read())
    elif not path or not pathlib.Path(path).exists():
        loc=taskfile or ''
        if taskfile:
            extra=''
        elif '--dir' in argv or '-d' in argv or any(a.startswith('--dir=') for a in argv):
            extra=' (or any of the parent directories until ownership changed).'
        else:
            extra=' (or any of the parent directories until ownership changed).'
        print(f'task: No Taskfile found at "{loc}"{extra} Run `task --init` to create a new Taskfile.',file=sys.stderr); return 100
    else:
      try: cfg=parse_yaml(pathlib.Path(path).read_text())
      except Exception as e:
        display=taskfile or pathlib.Path(path).name
        print(f'task: Failed to parse {display}:\n{e}',file=sys.stderr)
        return 109
    if not cfg.get('version'):
        shown=taskfile or path or ''
        print(f'task: Missing schema version in Taskfile "{shown}"',file=sys.stderr)
        return 107
    version=str(cfg.get('version')).lstrip('v')
    parts=version.split('.')

