def render(template, context=None):
    """Render common Go text/template interpolation and conditional blocks."""
    ctx = context or {}
    s = str(template)
    # Expand range loops, with optional Go-template variable declarations.
    range_pat = re.compile(r"{{\s*range\s+(?:(\$[A-Za-z_]\w*(?:\s*,\s*\$[A-Za-z_]\w*)?)\s*:=\s*)?([^}]+?)\s*}}", re.S)
    for _ in range(30):
        m = range_pat.search(s)
        if not m: break
        bounds=_block_at(s,m)
        if not bounds: break
        body=s[m.end():bounds[0]]
        var, expr = m.groups()
        seq = _value(expr, ctx)
        if isinstance(seq, dict): seq = list(seq.items())
        if isinstance(seq,str):seq=list(seq)
        if not isinstance(seq, (list, tuple)): seq = []
        chunks=[]
        for index, item in enumerate(seq):
            subctx=dict(ctx); subctx['.']=item; subctx['__dot__']=item
            if var:
                declared=[v.strip().lstrip('$') for v in var.split(',')]
                if len(declared)==1: subctx[declared[0]]=item
                else: subctx[declared[0]]=index; subctx[declared[1]]=item
            rendered=render(body, subctx)
            if '\x00TASK_BREAK\x00' in rendered or '{{break}}' in rendered:
                marker='\x00TASK_BREAK\x00' if '\x00TASK_BREAK\x00' in rendered else '{{break}}'
                chunks.append(rendered.split(marker,1)[0])
                break
            chunks.append(rendered)
        s=s[:m.start()] + ''.join(chunks) + s[bounds[1]:]
    # Basic if/else/end blocks; process innermost blocks first.
    pat = re.compile(r"{{\s*if\s+(.+?)\s*}}", re.S)
    for _ in range(30):
        m = pat.search(s)
        if not m: break
        bounds=_block_at(s,m)
        if not bounds: break
        body=s[m.end():bounds[0]]
        halves = re.split(r"{{\s*else\s*}}", body, maxsplit=1)
        replacement = halves[0] if _truth(_value(m.group(1),ctx)) else (halves[1] if len(halves)>1 else "")
        s = s[:m.start()] + replacement + s[bounds[1]:]
    def sub(m):
        if m.group(1).strip() == 'break': return '\x00TASK_BREAK\x00'
        val = _value(m.group(1),ctx)
        if val is None: return ""
        if isinstance(val, bool): return str(val).lower()
        return _format(val)
    return re.sub(r"{{\s*(.*?)\s*}}", sub, s).replace('\x00TASK_BREAK\x00','{{break}}')


def resolve_vars(variables, inherited=None, env=None, cwd=None):
    """Resolve simple static/ref Taskfile vars in declaration order."""
    result = dict(inherited or {})
    result.update(env or {})
    for key, raw in (variables or {}).items():
        if isinstance(raw, dict) and "ref" in raw:
            val = _lookup(str(raw["ref"]), result)
        elif isinstance(raw, dict) and "map" in raw:
            val = raw["map"]
        elif isinstance(raw, dict) and "sh" in raw:
            try:
                val = subprocess.check_output(raw["sh"],shell=True,cwd=cwd,env=env,text=True).rstrip("\n")
            except Exception: val = ""
        elif isinstance(raw, dict):
            val = raw.get("value", "")
        else:
            val = raw
        if isinstance(val, str): val = render(val, result)
        result[key] = val
    return result
